SELECT p.id, p.plate_no AS plateNo, p.plate_color AS plateColor, p.confidence, p.image_url AS imageUrl, p.status, s.name AS stationName, p.station_id AS stationId, p.remark, p.is_corrected AS isCorrected, p.reserve1, p.reserve2, p.creator, p.updater, p.create_time AS createTime, p.update_time AS updateTime FROM plate_identify p LEFT JOIN station_info s ON p.station_id = s.id WHERE p.deleted = 0
AND p.plate_no LIKE CONCAT('%', #{query.plateNo}, '%')
AND p.plate_color = #{query.plateColor}
AND p.confidence = #{query.confidence}
AND p.status = #{query.status}
AND p.station_id = #{query.stationId}
AND p.remark LIKE CONCAT('%', #{query.remark}, '%')
AND p.is_corrected = #{query.isCorrected}
ORDER BY p.id DESC

SELECT COUNT(*) AS total, SUM(CASE WHEN pi.status = '识别成功' THEN 1 ELSE 0 END) AS successNum, AVG(pi.duration) AS avgDuration, MAX(s.name) AS stationName FROM plate_identify pi INNER JOIN station_info s ON pi.station_id = s.id WHERE pi.deleted = 0
AND pi.create_time >= FROM_UNIXTIME(#{startTime}) AND pi.create_time <= FROM_UNIXTIME(#{endTime})
AND pi.station_id = #{stationId}
